PROBES <- [(1,1), (1,0), (0,1), (0,0), (1/2,1/2), (1/2,0), (0,1/2)]

function AFFINE_ERROR(h, lam, mu, nu, kappa, x, y):
    return lam*PROD_GATE(h,x,y) + mu*SOFT_SQUARE(h,x)
         + nu*SOFT_SQUARE(h,y) + kappa - x*y

function BARRIER_CERTIFICATE(h, lam, mu, nu, kappa):
    require 0 < h <= 1/2
    for each p in PROBES:
        err[p] <- AFFINE_ERROR(h, lam, mu, nu, kappa, p.x, p.y)
    witness <- argmax_p |err[p]|

    function MIXED(s):                    # kills mu, nu, kappa exactly
        E <- (x,y) -> AFFINE_ERROR(h, lam, mu, nu, kappa, x, y)
        return E(s,s) - E(s,0) - E(0,s) + E(0,0)

    return { witness,
             worst_error      = |err[witness]|,      # always >= h^2/210
             certified_floor  = h^2 / 210,
             mixed_corner     = MIXED(1),   reduced_corner = lam*P_h(1,1) - 1,
             mixed_half       = MIXED(1/2), reduced_half   = lam*P_h(.5,.5) - 1/4 }
